#include <stdio.h>
#include <stdint.h>

#define OPJ_UINT8 uint8_t
#define OPJ_UINT32 uint32_t
#define OPJ_BOOL uint8_t
#define OPJ_TRUE 1
#define OPJ_FALSE 0

OPJ_BOOL decode_rle4_bitmap(FILE* IN, OPJ_UINT8* pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    if (!IN || !pData || width == 0 || height == 0 || stride < width) {
        return OPJ_FALSE;
    }

    OPJ_UINT32 row = 0;
    OPJ_UINT32 col = 0;
    OPJ_UINT8* current_row = pData;

    while (row < height) {
        OPJ_UINT8 byte;
        if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
            return OPJ_FALSE;
        }

        if (byte == 0x00) {
            // End of line
            if (row + 1 < height) {
                current_row = pData + (row + 1) * stride;
                row++;
                col = 0;
            } else {
                return OPJ_FALSE; // Invalid end of line marker
            }
        } else if (byte == 0xFF) {
            // End of packet
            break;
        } else {
            // Read next byte to determine the mode
            OPJ_UINT8 mode;
            if (fread(&mode, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }

            if (mode == 0x00) {
                // Absolute mode
                while (col < width) {
                    if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                        return OPJ_FALSE;
                    }

                    if (byte == 0x00) {
                        // End of line
                        if (row + 1 < height) {
                            current_row = pData + (row + 1) * stride;
                            row++;
                            col = 0;
                        } else {
                            return OPJ_FALSE; // Invalid end of line marker
                        }
                        break;
                    } else if (byte == 0xFF) {
                        // End of packet
                        return OPJ_TRUE;
                    } else {
                        // Read next byte for count
                        OPJ_UINT8 count = byte;
                        if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                            return OPJ_FALSE;
                        }

                        OPJ_UINT32 remaining = width - col;
                        OPJ_UINT32 to_copy = (count + 1) * 2;
                        if (to_copy > remaining) {
                            to_copy = remaining;
                        }

                        for (OPJ_UINT32 i = 0; i < to_copy; i += 2) {
                            if (col >= width) {
                                return OPJ_FALSE; // Exceeding width
                            }
                            current_row[col++] = (byte >> 4) & 0x0F;
                            if (col >= width) {
                                return OPJ_FALSE; // Exceeding width
                            }
                            current_row[col++] = byte & 0x0F;
                            if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                                return OPJ_FALSE;
                            }
                        }
                    }
                }
            } else {
                // Encoded mode
                while (col < width) {
                    if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                        return OPJ_FALSE;
                    }

                    if (byte == 0x00) {
                        // End of line
                        if (row + 1 < height) {
                            current_row = pData + (row + 1) * stride;
                            row++;
                            col = 0;
                        } else {
                            return OPJ_FALSE; // Invalid end of line marker
                        }
                        break;
                    } else if (byte == 0xFF) {
                        // End of packet
                        return OPJ_TRUE;
                    } else {
                        // Read next byte for count
                        OPJ_UINT8 count = byte;
                        if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                            return OPJ_FALSE;
                        }

                        OPJ_UINT32 remaining = width - col;
                        OPJ_UINT32 to_copy = (count + 1) * 2;
                        if (to_copy > remaining) {
                            to_copy = remaining;
                        }

                        for (OPJ_UINT32 i = 0; i < to_copy; i += 2) {
                            if (col >= width) {
                                return OPJ_FALSE; // Exceeding width
                            }
                            current_row[col++] = (byte >> 4) & 0x0F;
                            if (col >= width) {
                                return OPJ_FALSE; // Exceeding width
                            }
                            current_row[col++] = byte & 0x0F;
                        }
                    }
                }
            }
        }
    }

    return (row == height) ? OPJ_TRUE : OPJ_FALSE;
}
